365	fn resolve_taking(
366	    mut request: SemanticRequest,
367	    reads: Option<Arc<kept::Reads>>,
368	    early: Option<EarlyStart>,
369	) -> (SemanticOutcome, Taken) {
370	    request.heap_budget.get_or_insert_with(HeapBudget::machine);
371	    let teardown = request.teardown;
372	    let files = root_files(&request);
373	    let early = early.and_then(|early| {
374	        let roots = early.roots;
375	        early.handle.and_then(|handle| handle.join().ok().flatten()).map(|opened| (roots, opened))
376	    });
377	    if let Some((early_roots, opened)) = early {
378	        let Opened { runtime, checker, programs } = opened;
379	        let same = early_roots == files;
380	        let adopted = match programs {
381	            Ok(programs) if same => Some((Ok(programs), Taken::Same)),
382	            Err(unavailable) if same => Some((Err(unavailable), Taken::Same)),
383	            // An early start that failed to open for other files did not fail for these: they are opened again.
384	            Err(_) => None,
385	            Ok(programs) if files.is_empty() => {
386	                drop(programs);
387	                None
388	            }
389	            Ok(programs) => match runtime.block_on(reroot(programs, &files)) {
390	                Ok(programs) => Some((Ok(programs), Taken::Rooted)),
391	                Err(error) => {
392	                    tracing::debug!(%error, "the session opened early could not be rooted at the request's files");
393	                    None
394	                }
395	            },
396	        };
397	        match adopted {
398	            Some((programs, taken)) => {
399	                tracing::debug!(
