/// This session holding the snapshots of `lanes`, the other lanes of its run: [`Rpc::release`] and
/// [`Rpc::release_lanes`] on it release them, and nothing else may.
pub(crate) fn holding(self, lanes: &[Rpc]) -> Rpc {
    let mut others = self.take_lanes();
    others.extend(lanes.iter().map(|rpc| rpc.snapshot));
    Rpc { others: Mutex::new(others), ..self }
}

