                    (present.into_iter().map(String::from).collect(), gone.into_iter().map(String::from).collect())
                };
                let rerooted = (live.roots != roots).then_some(roots.as_slice());
                match live.rpc.updated(&changed, &deleted, rerooted).await {
                    Ok(rpc) => {
