    let rpc = Arc::new(Rpc::open_with(client, deadline, options, &roots, false).await?);
    self.gauges.created.fetch_add(1, Ordering::Relaxed);
    self.live = Some(Live { rpc: rpc.clone(), roots, read_from, stamps: None });
    Ok((rpc, warning))
}

